 /** FIPS 197-upd1 §4: coefficients in GF(2), modulus x^8+x^4+x^3+x+1. */
 export const add=(a:number,b:number)=>a^b;
-export function xtime(a:number):number{return ((a<<1)^((a&0x80)?0x1b:0))&255;}
+export function xtime(a:number):number{return ((a<<1)^0x1b)&255;}
 export function mul(a:number,b:number):number{let v=0;for(let i=0;i<8;i++){if(b&1)v^=a;a=xtime(a);b>>>=1;}return v;}
 const degree=(p:number)=>31-Math.clz32(p);
 export function polynomialMultiply(a:number,b:number):number{let v=0;while(b){if(b&1)v^=a;a<<=1;b>>>=1;}return v;}

